# summarize non-bg components of current test
from collections import deque,Counter
H=len(grid);W=len(grid[0]); bg=2; seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if grid[r][c]==bg or (r,c) in seen: continue
  color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   y,x=q.pop();cells.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<H and 0<=xx<W and (yy,xx) not in seen and grid[yy][xx]==color:
     seen.add((yy,xx));q.append((yy,xx))
  comps.append((color,cells))
for co,cs in comps:
 print(co,len(cs),(min(r for r,c in cs),min(c for r,c in cs),max(r for r,c in cs),max(c for r,c in cs)),sorted(cs))

